W += c[15]*30.026000; // CH2O
W += c[16]*29.018000; // HCO
W += c[17]*30.026000; // HCOH
W += c[18]*30.070000; // C2H6
W += c[19]*29.062000; // C2H5
W += c[20]*62.068000; // C2H5O2H
W += c[21]*61.060000; // C2H5O2
