W += c[24]*58.036000; // CHOCHO
W += c[25]*59.044000; // C2H3OO
W += c[26]*42.037000; // CHCHO
W += c[27]*26.038000; // C2H2
W += c[28]*45.061000; // C2H5O
W += c[29]*45.061000; // PC2H4OH
W += c[30]*77.059000; // O2C2H4OH
W += c[31]*43.045000; // CH2CHO
W += c[32]*42.037000; // CH2CO
W += c[33]*41.029000; // HCCO
W += c[34]*44.097000; // C3H8
W += c[35]*43.089000; // IC3H7
W += c[36]*43.089000; // NC3H7
W += c[37]*75.087000; // C3H6OOH1-2
W += c[38]*75.087000; // C3H6OOH1-3
W += c[39]*42.081000; // C3H6
W += c[40]*41.073000; // C3H5-A
W += c[41]*57.072000; // CH3CHCHO
W += c[42]*57.072000; // C3H5O
W += c[43]*74.079000; // AC3H5OOH
W += c[44]*40.065000; // C3H4-P
W += c[45]*40.065000; // C3H4-A
W += c[46]*39.057000; // C3H3
W += c[47]*38.049000; // C3H2
W += c[48]*56.064000; // C2H3CHO
W += c[49]*55.056000; // C2H3CO
W += c[50]*100.205000; // NC7H16
W += c[51]*99.197000; // C7H15
W += c[52]*131.195000; // C7H15O2
W += c[53]*131.195000; // C7H14OOH
W += c[54]*163.193000; // O2C7H14OOH
W += c[55]*146.186000; // C7KET
W += c[56]*99.153000; // C5H11CO
W += c[57]*114.232000; // IC8H18
