XW += x[37]*75.087000; // C3H6OOH1-2
XW += x[38]*75.087000; // C3H6OOH1-3
XW += x[39]*42.081000; // C3H6
XW += x[40]*41.073000; // C3H5-A
XW += x[41]*57.072000; // CH3CHCHO
XW += x[42]*57.072000; // C3H5O
XW += x[43]*74.079000; // AC3H5OOH
XW += x[44]*40.065000; // C3H4-P
XW += x[45]*40.065000; // C3H4-A
XW += x[46]*39.057000; // C3H3
XW += x[47]*38.049000; // C3H2
XW += x[48]*56.064000; // C2H3CHO
XW += x[49]*55.056000; // C2H3CO
XW += x[50]*100.205000; // NC7H16
XW += x[51]*99.197000; // C7H15
XW += x[52]*131.195000; // C7H15O2
XW += x[53]*131.195000; // C7H14OOH
XW += x[54]*163.193000; // O2C7H14OOH
