qr[10] = sc[19];

// reaction 155: C2H2 + H (+M) <=> C2H3 (+M)
qf[11] = sc[2]*sc[27];
qr[11] = sc[23];

// reaction 246: CH2 + CO (+M) <=> CH2CO (+M)
qf[12] = sc[9]*sc[13];
qr[12] = sc[32];

// reaction 259: C2H5O (+M) <=> CH2O + CH3 (+M)
