// reaction 35: 2 O + M <=> O2 + M
qf[18] = (sc[4] * sc[4]);
qr[18] = sc[3];

// reaction 39: H + O + M <=> OH + M
qf[19] = sc[2]*sc[4];
qr[19] = sc[6];

// reaction 99: CH2O + H => CO + H2 + H
qf[20] = sc[2]*sc[15];
qr[20] = 0.0;

// reaction 100: HCO + M <=> CO + H + M
qf[21] = sc[16];
