           * exp((-0.5) * logT);
Corr  = mixture + (1.5)*sc[1] + (11)*sc[5] + (0.9)*sc[9] + (2.8)*sc[10] + sc[11] + (2)*sc[18];
qf[18] *= Corr * k_f;
