           * exp((0.234) * logT - (-57.366699901738) * invT);
Corr  = mixture + (1.5)*sc[1] + (9.4)*sc[5];
redP = Corr / k_f * 22000000000 
           * exp(-2  * logT);
F = redP / (1.0 + redP);
logPred = log10(redP);
logFcent = log10(
    (0.27)*exp(-T * 1e+30)
    + 0.73 * exp(-T * 1e-30)
    + exp(-1e+30 * invT));
troe_c = -0.4 - 0.67 * logFcent;
troe_n = 0.75 - 1.27 * logFcent;
troe = (troe_c + logPred) / (troe_n - 0.14*(troe_c + logPred));
F_troe = exp(M_LN10 * logFcent / (1.0 + troe*troe));
Corr = F * F_troe;
qf[0] *= Corr * k_f;
qr[0] *= Corr * k_f * exp(-(g_RT[2] - g_RT[5] + g_RT[6])) * (refC);
