// reaction 39:  H + O + M <=> OH + M
k_f = 4714000
           * exp((-1) * logT);
Corr  = mixture + (1.5)*sc[1] + (11)*sc[5] + (0.5)*sc[9] + sc[10] + sc[11] + (2)*sc[18];
qf[19] *= Corr * k_f;
