           * exp((0.9) * logT - (24531.3092413143) * invT);
Corr  = mixture + (0.5)*sc[0] + (2.7)*sc[1] + (-0.21)*sc[3] + (4.1)*sc[5] + (4.2)*sc[7] + (1.8)*sc[9] + (0.0600000000000001)*sc[10];
redP = Corr / k_f * 2.3530181e+18 
           * exp(-2.2929358  * logT - (24528.4937440691) *invT);
