qr[66] *= k_f * exp(-(-g_RT[3] - g_RT[5] + g_RT[6] + g_RT[8]));
// reaction 50:  HO2 + OH <=> H2O + O2
k_f = 1210
           * exp((1.24) * logT - (-657.996047872935) * invT);
