qr[67] *= k_f * exp(-(-g_RT[3] - g_RT[5] + g_RT[6] + g_RT[8]));
// reaction 51:  2 HO2 <=> H2O2 + O2
k_f = 12140
           * exp((0.422) * logT - (-745.022338057204) * invT);
