qr[68] *= k_f * exp(-(-g_RT[3] - g_RT[7] + 2.000000*g_RT[8]));
// reaction 52:  2 HO2 <=> H2O2 + O2
k_f = 16880000000
           * exp((-0.681) * logT - (6507.42682852026) * invT);
